<section class="course-hero section-shell"><div><p class="eyebrow"><?= e($course['category']) ?> · <?= e($course['difficulty']) ?></p><h1><?= e($course['title']) ?></h1><p class="lede"><?= e($course['short_description']) ?></p><div class="meta-row"><span><?= (int) $course['estimated_minutes'] ?> minutes</span><span><?= $course['access_level'] === 'premium' ? 'Premium access' : 'Free course' ?></span><?php if ($course['instructor_name']): ?><span>By <?= e($course['instructor_name']) ?></span><?php endif; ?></div></div><aside class="enrol-card"><span class="tag"><?= $course['access_level'] === 'premium' ? 'Premium' : 'Free' ?></span><h2><?= $enrolled ? 'You’re enrolled' : 'Ready when you are' ?></h2><p><?= $course['access_level'] === 'premium' ? 'An active plan is required for full access.' : 'Start the first lesson at no cost.' ?></p><?php if ($enrolled): ?><a class="button" href="<?= route('dashboard') ?>">Resume learning</a><?php elseif ($user): ?><form method="post" action="index.php"><?= csrf_field() ?><input type="hidden" name="action" value="enroll"><input type="hidden" name="course_id" value="<?= (int) $course['id'] ?>"><input type="hidden" name="return_page" value="course"><button class="button" type="submit">Enrol now</button></form><?php else: ?><a class="button" href="<?= route('register') ?>">Create a free account</a><?php endif; ?></aside></section>
<section class="section-shell course-detail"><article><h2>What you’ll learn</h2><p><?= e($course['description']) ?></p><h2>Course lessons</h2><div class="syllabus"><?php foreach ($course['modules'] as $item): ?><div class="syllabus-row"><span class="lesson-index"><?= $item['lesson_id'] ? '↳' : '—' ?></span><div><strong><?= e($item['lesson_title'] ?? $item['title']) ?></strong><?php if ($item['lesson_id']): ?><small><?= (int) $item['lesson_minutes'] ?> min <?= (int) $item['is_free_preview'] ? '· Free preview' : '' ?></small><?php endif; ?></div><?php if ($item['lesson_id']): ?><a href="<?= route('lesson', ['id' => $item['lesson_id']]) ?>"><?= (int) $item['is_free_preview'] ? 'Preview' : 'Open' ?> →</a><?php endif; ?></div><?php endforeach; ?></div></article><aside><h2>Before you start</h2><p>Bring curiosity and a few focused minutes. Each lesson explains the next step before it expects you to use it.</p><h3>Learning approach</h3><ul class="check-list"><li>Clear examples</li><li>Guided practice</li><li>Progress you can return to</li></ul></aside></section>
